const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), uid=()=>crypto.randomUUID(), today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Zurich'}).format(new Date()), fmt=d=>d?d.split('-').reverse().join('.'):'Termin offen', money=n=>Number(n||0).toLocaleString('de-CH',{style:'currency',currency:'CHF'});
