const seed=[['1','Neubau: Decke 1. OG aufgenagelt','2026-11-10','2026-11-10','Erledigt'],['1','Elektroeinlagen Decke 1. OG','2026-11-12','2026-11-12'],['1','Anbau Altbau: Wandeinlagen 1. OG','','','In Arbeit'],['1','Altbau: Rohre Rohboden 2. OG und DG verlegt','','','Erledigt'],['1','Wichmannboxen nach Ausschalung einbauen','','','','Ausschalung durch Holzbauer abwarten'],['1','Bodendosen vor Unterlagsboden montieren','','','','Bodendosen vor Ort; zwingend vor Unterlagsboden'],['2','Decke UG vollständig betoniert','','','Erledigt'],['2','Wandeinlagen EG REFH abgeschlossen','','','Erledigt'],['2','Wandeinlagen EG MFH','','','In Arbeit'],['2','Zwei Käuferbesprechungen organisieren'],['2','Nachträge durch Käufer freigeben lassen'],['2','Elektropläne anpassen und Käufern zur Freigabe zustellen','','','','Nach Freigabe der Nachträge'],['3','Häuser I1 / I2: Inbetriebnahme und Funktionsprüfungen'],['3','Häuser J1–J4: Restarbeiten und Inbetriebnahmen'],['3','Häuser C1 / C2: Elektroinstallationen','','','In Arbeit'],['3','Pronovo: Meldungen und Unterlagen erstellen und einreichen'],['4','Endmontage Elektroinstallationen','','','In Arbeit'],['4','Zählermontage','2026-11-11','2026-11-11','','13:30 Uhr'],['4','Inbetriebnahme Lüftungsanlagen','2026-11-19','2026-11-19'],['5','Baustart: Rohbauinstallationen UG und Steigzonen','2026-11-23','2026-11-23'],['6','Rohre im Rohboden verlegt','','','Erledigt'],['6','Rohbauinstallationen Wände','2026-11-13','2027-01-07'],['7','Photovoltaikanlage vergeben','','','','Prioritär'],['7','Dach voraussichtlich montagebereit (KW 49)','2026-11-30','2026-12-06','','Zeitfenster, noch zu bestätigen'],['7','Lieferung Unterkonstruktion (KW 50)','2026-12-07','2026-12-13','','Vorgesehenes Zeitfenster'],['7','Kranzüge beim Polier anmelden und koordinieren']];
