let db,page='Dashboard',gstart='2026-11-09';
const tabs=['Dashboard','Aufgaben','Gantt & Ressourcen','Rapporte & Journal','Rapportstudio','Materialbestellungen','Jour fixe','Dokumente','Debitoren','Management','KI-Hilfe','Anleitung'];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
const openDB=()=>new Promise((resolve,reject)=>{let r=indexedDB.open('navolta-philippe-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>{db=r.result;resolve()};r.onerror=()=>reject(r.error)});
async function save(){return new Promise((resolve,reject)=>{let t=db.transaction('data','readwrite');t.objectStore('data').put(state,'state');t.oncomplete=resolve;t.onerror=()=>{toast('Speichern fehlgeschlagen: bitte Datensicherung erstellen.');reject(t.error)}})}
function chosen(){return $('#project').value}function projectName(id){return state.projects.find(p=>p.id===id)?.name||''}function match(x){return (!chosen()||x.project===chosen())&&JSON.stringify(x).toLowerCase().includes($('#search').value.toLowerCase())}function tasks(){return state.tasks.filter(match)}function overdue(x){return x.status!=='Bezahlt'&&x.due&&x.due<today()&&Number(x.amount)>Number(x.paid||0)}function balance(x){return Math.max(0,Number(x.amount)-Number(x.paid||0))}function nav(p){page=p;render()}
function render(){ $('#nav').innerHTML=tabs.map((t,i)=>`<button class="${page===t?'active':''}" onclick="nav('${t}')">${['◈','✓','▥','▤','▣','▰','◷','▱','₣','↗','✧','?'][i]} &nbsp; ${t}</button>`).join('');$('#heading').textContent=page==='Dashboard'?'Guten Tag, Philippe.':page;$('#today').textContent=new Date().toLocaleDateString('de-CH',{weekday:'long',day:'numeric',month:'long',timeZone:'Europe/Zurich'});let v=$('#view');
if(page==='Dashboard'){let ts=tasks(),open=ts.filter(t=>t.status!=='Erledigt'),inv=state.invoices.filter(match);v.innerHTML=`<div class="hero"><div><small>ALLES IM BLICK. JEDEN TAG.</small><h2>Sieben Projekte. Ein Cockpit.</h2><p>Aufgaben, Baustellen und Finanzen an einem Ort.</p></div></div><div class="stats"><div class="stat">Aktive Projekte<strong>${chosen()?1:state.projects.length}</strong><small>Projektportfolio</small></div><div class="stat">Offene Aufgaben<strong>${open.length}</strong><small>${open.filter(t=>t.priority==='Hoch').length} mit hoher Priorität</small></div><div class="stat">Termine heute<strong>${open.filter(t=>t.start<=today()&&t.end>=today()).length}</strong><small>${fmt(today())}</small></div><div class="stat">Offene Debitoren<strong style="font-size:24px">${money(inv.reduce((a,b)=>a+balance(b),0))}</strong><small>${inv.filter(overdue).length} überfällige Rechnungen</small></div></div><div class="row"><h2>Projektübersicht</h2><button onclick="editProject()">+ Projekt</button></div><div class="grid">${state.projects.filter(p=>!chosen()||p.id===chosen()).map(p=>{let a=state.tasks.filter(t=>t.project===p.id),n=a.filter(t=>t.status==='Erledigt').length;return `<article class="card projectcard"><div class="row"><h3>${esc(p.name)}</h3><span class="pill">${a.length-n} offen</span></div><p>${esc(p.description)}</p><progress value="${n}" max="${a.length||1}" style="width:100%"></progress><div class="row" style="margin-top:15px"><small class="muted">${n} / ${a.length} erledigt</small><button onclick="$('#project').value='${p.id}';nav('Aufgaben')">Projekt öffnen →</button></div></article>`}).join('')}</div>`}
if(page==='Aufgaben')v.innerHTML=`<div class="row"><p class="muted">Termine, Zuständigkeiten und Nachweise pro Tätigkeit.</p><button class="primary" onclick="editTask()">+ Aufgabe</button></div>${taskTable(tasks())}`;
if(page==='Gantt & Ressourcen')gantt(v);
if(page==='Materialbestellungen'){let rows=state.materialOrders.filter(match),total=rows.reduce((a,o)=>a+Number(o.amount||0),0);v.innerHTML=`<div class="note">Bestellungen projektbezogen erfassen und Lieferscheine direkt zur jeweiligen Bestellung ablegen. Die Dateien sind über Dokumente und die Bestellung wieder aufrufbar.</div><div class="stats"><div class="stat">Bestellungen<strong>${rows.length}</strong><small>im ausgewählten Umfang</small></div><div class="stat">Offen / unterwegs<strong>${rows.filter(o=>o.status!=='Abgeschlossen'&&o.status!=='Storniert').length}</strong></div><div class="stat">Bestellwert<strong style="font-size:24px">${money(total)}</strong><small>erfasste Beträge inkl. MWST</small></div><div class="stat">Lieferscheine<strong>${rows.reduce((a,o)=>a+state.files.filter(f=>f.parent===o.id).length,0)}</strong><small>zugeordnet</small></div></div><div class="actions"><button class="primary" onclick="editMaterialOrder()">+ Materialbestellung</button><button onclick="uploadDialog()">Dokument separat ablegen</button></div><div class="tablewrap"><table><tr><th>Bestellung / Material</th><th>Projekt / Lieferant</th><th>Bestellt / Lieferung</th><th>Betrag</th><th>Status</th><th>Lieferscheine / Aktionen</th></tr>${rows.map(o=>`<tr><td><b>${esc(o.number||'Ohne Bestellnummer')}</b><small>${esc(o.title)}</small></td><td>${esc(projectName(o.project))}<small>${esc(o.supplier||'Lieferant offen')}</small></td><td>${fmt(o.date)}<small>Lieferung: ${fmt(o.delivery)}</small></td><td>${o.amount?money(o.amount):'Offen'}</td><td><span class="pill ${o.status==='Abgeschlossen'?'green':o.status==='Verspätet'?'red':''}">${esc(o.status||'Bestellt')}</span></td><td>${fileLinks(o.id)}<button onclick="editMaterialOrder('${o.id}')">Bearbeiten / Lieferschein ablegen</button></td></tr>`).join('')}</table></div>${rows.length?'':'<div class="empty">Noch keine Materialbestellungen erfasst.</div>'}`;}
if(page==='Rapportstudio')v.innerHTML=`<div class="row"><div><h2>Navolta Rapportstudio</h2><p class="muted">Das bestehende Rapportstudio ist hier direkt eingebunden. Es bleibt die massgebende Arbeitsoberfläche für Regierapporte, PDF-Scan, Mitarbeitende, Ansätze, Belege und Auftragssummen.</p></div><a class="button primary" href="https://simonerhard.github.io/Navolta-APP/rapportstudio/" target="_blank" rel="noopener">In neuem Fenster öffnen ↗</a></div><iframe title="Navolta Rapportstudio" src="https://simonerhard.github.io/Navolta-APP/rapportstudio/" style="width:100%;height:calc(100vh - 230px);min-height:700px;border:1px solid var(--line);border-radius:10px;background:white" allow="clipboard-read; clipboard-write"></iframe><p class="muted">Wenn dein Browser das Einbetten oder die Anmeldung im Fenster blockiert, öffne das Rapportstudio über den Button oben.</p>`;
if(page==='Rapporte & Journal'||page==='Jour fixe'){let type=page==='Jour fixe'?'Jour fixe':null,rows=state.entries.filter(match).filter(e=>type?e.type===type:e.type!=='Jour fixe'),reports=rows.filter(e=>e.type==='Rapport'),verifiedReports=reports.filter(e=>e.verified),sumHours=verifiedReports.reduce((a,e)=>a+Number(e.hours||0),0),sumAmount=verifiedReports.reduce((a,e)=>a+reportAmount(e),0);v.innerHTML=`<div class="actions"><button class="primary" onclick="editEntry(null,'${type||'Rapport'}')">+ ${type||'Rapport'}</button>${!type?`<button onclick="editEntry(null,'Baustellenjournal')">+ Journaleintrag</button><button onclick="editEmployees()">Mitarbeitende & Ansätze (${state.employees.length})</button><button onclick="exportRapportCSV()">Rapportübersicht CSV</button>`:''}</div>${!type?`<div class="stats"><div class="stat">Rapporte<strong>${reports.length}</strong></div><div class="stat">Geprüfte Stunden<strong>${sumHours.toFixed(2)}</strong></div><div class="stat">Beträge<strong style="font-size:24px">${money(sumAmount)}</strong></div><div class="stat">Aufträge<strong>${new Set(reports.map(e=>e.order).filter(Boolean)).size}</strong></div></div><div class="tablewrap"><table><tr><th>Auftrag</th><th>Rapporte</th><th>Stunden</th><th>Betrag CHF</th></tr>${[...new Set(reports.map(e=>e.order||'Ohne Auftragsnummer'))].map(o=>{let a=verifiedReports.filter(e=>(e.order||'Ohne Auftragsnummer')===o);return `<tr><td>${esc(o)}</td><td>${a.length}</td><td>${a.reduce((s,e)=>s+Number(e.hours||0),0).toFixed(2)}</td><td>${money(a.reduce((s,e)=>s+reportAmount(e),0))}</td></tr>`}).join('')}</table></div>`:''}<div class="grid">${rows.map(e=>`<article class="card"><div class="row"><span class="pill">${esc(e.type)}</span><small>${fmt(e.date)}</small></div><h3 style="margin-top:16px">${esc(e.title)}</h3><p class="muted">${esc(projectName(e.project))} · ${esc(e.employee||e.owner||'Verantwortliche offen')} · ${Number(e.hours||0).toFixed(2)} h · ${money(reportAmount(e))}</p>${e.order?`<p>Auftrag: ${esc(e.order)}</p>`:''}<p style="white-space:pre-wrap">${esc(e.text)}</p>${fileLinks(e.id)}<div class="photos">${state.files.filter(f=>f.parent===e.id&&f.type.startsWith('image/')).map(f=>`<img src="${f.data}" alt="${esc(f.name)}">`).join('')}</div><div class="actions"><button onclick="editEntry('${e.id}')">Bearbeiten</button><button onclick="copyEntry('${e.id}')">Kopieren</button><button onclick="exportReport('pdf','${e.id}')">PDF</button><button onclick="exportReport('docx','${e.id}')">Word</button></div><small class="muted">${esc(e.history||'')}</small></article>`).join('')||'<div class="card empty">Noch keine Einträge. Fotos und PDFs können direkt angehängt werden.</div>'}</div>`}
if(page==='Dokumente')v.innerHTML=`<div class="note">PDF, Fotos und Office-Dateien projektbezogen oder an einzelne Aufgaben, Rapporte, Rechnungen und Jour-fixe-Protokolle ablegen. Text-PDFs werden ausgelesen; Scans können per OCR erkannt werden.</div><div class="actions"><button class="primary" onclick="uploadDialog()">+ Dokument ablegen</button><a class="button" href="assets/Vorlage.docx" download>Original-Wordvorlage</a></div><div class="tablewrap"><table><tr><th>Dokument</th><th>Projekt / Zuordnung</th><th>Verarbeitung</th></tr>${state.files.filter(match).map(f=>`<tr><td><a href="${f.data}" download="${esc(f.name)}">${esc(f.name)}</a><small>${(f.size/1024).toFixed(0)} KB</small></td><td>${esc(projectName(f.project))}<small>${esc(parentName(f.parent))}</small></td><td><button onclick="processFile('${f.id}')">Text / OCR</button> <button onclick="removeFile('${f.id}')">Entfernen</button></td></tr>`).join('')}</table></div>`;
if(page==='Debitoren'){let rows=state.invoices.filter(match);v.innerHTML=`<div class="note">Zahlungsstatus manuell pflegen. Warnungen prüfen die erfassten Fälligkeiten beim Öffnen und während der Nutzung; es besteht keine Bankanbindung.</div><div class="actions"><button class="primary" onclick="editInvoice()">+ Rechnung erfassen / scannen</button><button onclick="paymentAlert(true)">Fälligkeiten prüfen</button></div><div class="stats"><div class="stat">Offen<strong style="font-size:24px">${money(rows.reduce((s,x)=>s+balance(x),0))}</strong></div><div class="stat">Überfällig<strong style="font-size:24px">${money(rows.filter(overdue).reduce((s,x)=>s+balance(x),0))}</strong></div></div><div class="tablewrap"><table><tr><th>Rechnung / Kunde</th><th>Fällig</th><th>Betrag / Rest</th><th>Status</th><th>Aktion</th></tr>${rows.map(x=>`<tr><td>${esc(x.number)} · ${esc(x.customer)}<small>${esc(projectName(x.project))}</small>${fileLinks(x.id)}</td><td>${fmt(x.due)}</td><td>${money(x.amount)}<small>Rest ${money(balance(x))}</small></td><td><span class="pill ${overdue(x)?'red':'green'}">${overdue(x)?'Überfällig':balance(x)===0?'Bezahlt':'Offen'}</span></td><td><button onclick="editInvoice('${x.id}')">Bearbeiten</button> <button onclick="reminder('${x.id}')">Mahnung</button></td></tr>`).join('')}</table></div>${!rows.length?'<div class="empty">Keine Rechnungen erfasst. Es wurden keine Beträge erfunden.</div>':''}`}
if(page==='Management')v.innerHTML=`<div class="card"><span class="pill">MANAGEMENT-REPORT</span><h2>Gesamte Tätigkeitsübersicht</h2><p>Aktueller Projektstatus, vollständige Aufgabenliste, Ressourcen, Rapporte und offene Debitoren. Der Projektfilter bestimmt den Umfang.</p><div class="actions"><button class="primary" onclick="exportReport('pdf')">↓ PDF erstellen</button><button onclick="exportReport('docx')">↓ Word erstellen</button><button onclick="exportXlsx()">↓ Excel erstellen</button><button class="primary" onclick="mailReport()">E-Mail-Entwurf erstellen (.eml)</button></div><p class="muted">Erstellt eine Outlook-kompatible EML-Datei mit PDF-Anhang. Empfänger vor Versand ergänzen und Entwurf prüfen.</p></div><h2>Tätigkeiten</h2>${taskTable(tasks(),true)}`;
if(page==='KI-Hilfe')v.innerHTML=`<div class="card"><span class="pill">ARBEITSVORBEREITUNG</span><h2>Projektkontext für die KI vorbereiten</h2><p>Projektinformationen und Dokumenttext werden zu einer kopierbaren Anfrage zusammengestellt. Diese Version enthält keinen integrierten KI-Dienst.</p><select id="aiKind"><option>Tagesprioritäten und offene Rückfragen erstellen</option><option>Professionellen Baustellenrapport formulieren</option><option>Jour-fixe-Agenda mit Pendenzen erstellen</option><option>Projektstatus für Management zusammenfassen</option><option>Dokument analysieren und Aufgaben vorschlagen</option></select><textarea id="aiExtra" placeholder="Zusätzliche Angaben oder ausgelesenen Dokumenttext einfügen …" style="margin-top:15px"></textarea><button class="primary" onclick="aiPrompt()">KI-Anfrage erstellen</button><textarea id="aiOut" style="margin-top:15px" placeholder="Die vorbereitete Anfrage erscheint hier."></textarea><button onclick="navigator.clipboard.writeText($('#aiOut').value).then(()=>toast('Anfrage kopiert')).catch(()=>toast('Bitte Text manuell kopieren'))">Kopieren</button><a class="button" href="https://chatgpt.com" target="_blank" rel="noopener">ChatGPT öffnen ↗</a></div>`;
if(page==='Anleitung')v.innerHTML=`<div class="card"><h2>So arbeitet Philippe mit dem Cockpit</h2><ol><li><p>Projekt auswählen. Aufgaben, Termine, Verantwortliche und Stunden ergänzen. Noch offene Termine bleiben leer.</p></li><li><p>Gantt: Balken ziehen verschiebt Start und Ende tageweise. Abhängigkeiten werden in Aufgaben festgelegt; Nachfolger werden bei Terminänderungen auf den nächsten Tag verschoben. Nicht terminierte Aufgaben erscheinen separat. Ressourcenbuchungen erfassen Name, Zeitraum und Stunden pro Arbeitstag.</p></li><li><p>Rapporte, Journal und Jour fixe erfassen. Fotos und PDFs direkt anhängen. Protokolle kopieren; Änderungen bleiben als Verlauf sichtbar.</p></li><li><p>Dokumente: Text/OCR liest PDF-Text oder Scanbilder. Erkennung prüfen; Rechnungsdaten werden vor dem Speichern manuell bestätigt. OCR nutzt englische Erkennungsdaten, Umlaute können ungenau sein.</p></li><li><p>Debitoren: Rechnung, Gesamtbetrag inkl. MWST, bereits bezahlten Betrag und Fälligkeit erfassen. Pop-up bei überfälligem Restbetrag. Zahlungen selbst nachführen. Mahnung vor Versand prüfen.</p></li><li><p>Outlook: In der Aufgabenliste „Outlook“ lädt eine ICS-Datei. In Outlook importieren; es erfolgt keine automatische Synchronisierung. Termine ohne Uhrzeit sind ganztägig.</p></li><li><p>Management: PDF, DOCX oder XLSX erstellen. E-Mail vorbereiten, Empfänger und Anhang hinzufügen. Kein automatischer Versand.</p></li><li><p>Datensicherung: JSON inklusive Anhängen täglich herunterladen und im vorgesehenen SharePoint-Ordner ablegen. Wiederherstellen ersetzt den gesamten Browserbestand. Daten werden lokal in IndexedDB gespeichert; es gibt keine gemeinsame Mehrbenutzerdatenbank.</p></li></ol><div class="note">Exportgestaltung: Arial-ähnliche Schrift im PDF, Arial in Word; Haupttitel 16 pt, Untertitel 14 pt und Text 12 pt entsprechend der hochgeladenen Vorlage. Navolta-Logo oben rechts. Die Originalvorlage steht unter Dokumente zur Verfügung.</div></div>`;
}
function taskTable(rows,readonly=false){return `<div class="tablewrap"><table><tr><th>Tätigkeit / Projekt</th><th>Zeitraum</th><th>Verantwortlich</th><th>Status</th>${readonly?'':'<th>Aktion</th>'}</tr>${rows.map(t=>`<tr><td>${esc(t.title)}<small>${esc(projectName(t.project))}${t.priority==='Hoch'?' · Hohe Priorität':''}</small>${t.note?`<small>${esc(t.note)}</small>`:''}${fileLinks(t.id)}</td><td>${fmt(t.start)}${t.end&&t.end!==t.start?'<small>bis '+fmt(t.end)+'</small>':''}</td><td>${esc(t.owner||'Noch zuweisen')}<small>${Number(t.hours)||0} h geplant</small></td><td><span class="pill ${t.status==='Erledigt'?'green':t.end&&t.end<today()?'red':''}">${esc(t.status)}</span></td>${readonly?'':`<td><button onclick="editTask('${t.id}')">Bearbeiten</button> <button onclick="calendar('${t.id}')">Outlook</button></td>`}</tr>`).join('')}</table></div>`}
function options(value){return state.projects.map(p=>`<option value="${p.id}" ${value===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}function input(name,label,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}function select(name,label,values,value){return `<label>${label}<select name="${name}">${values.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`}function show(html){$('#dialogcontent').innerHTML=html;$('#modal').showModal()}function parentName(id){return [...state.tasks,...state.entries,...state.invoices,...(state.materialOrders||[])].find(x=>x.id===id)?.title||[...state.invoices,...(state.materialOrders||[])].find(x=>x.id===id)?.number||'Projektablage'}function fileLinks(parent){return `<div class="files">${state.files.filter(f=>f.parent===parent).map(f=>`<a href="${f.data}" download="${esc(f.name)}">↧ ${esc(f.name)}</a>`).join('')}</div>`}
function editProject(){show(`<h2>Projekt anlegen</h2><form id="form">${input('name','Projektname','','text','required')}${input('description','Beschreibung')}<button class="primary">Speichern</button></form>`);$('#form').onsubmit=async e=>{e.preventDefault();state.projects.push({id:uid(),...Object.fromEntries(new FormData(e.target))});await save();projectSelect();$('#modal').close();render()}}
function projectSelect(){let val=$('#project').value;$('#project').innerHTML='<option value="">Alle Projekte</option>'+options();$('#project').value=val}
function editTask(id){let x=state.tasks.find(t=>t.id===id)||{id:uid(),project:chosen()||'1',status:'Offen',priority:'Normal'};show(`<h2>${id?'Aufgabe bearbeiten':'Neue Aufgabe'}</h2><form id="form"><label>Projekt<select name="project">${options(x.project)}</select></label>${input('title','Tätigkeit',x.title,'text','required')}<div class="fields">${input('start','Start',x.start,'date')}${input('end','Ende',x.end,'date')}${input('owner','Verantwortlich',x.owner)}${input('hours','Geplante Stunden',x.hours||0,'number','min="0" step="0.25"')}${select('status','Status',['Offen','In Arbeit','Blockiert','Erledigt'],x.status)}${select('priority','Priorität',['Normal','Hoch'],x.priority)}</div><label>Abhängigkeit (Vorgänger)<select name="depends"><option value="">Keine</option>${state.tasks.filter(t=>t.project===x.project&&t.id!==x.id).map(t=>`<option value="${t.id}" ${x.depends===t.id?'selected':''}>${esc(t.title)}</option>`).join('')}</select></label><label>Hinweis<textarea name="note">${esc(x.note)}</textarea></label><label>PDF / Nachweise / Fotos<input name="files" type="file" multiple></label>${fileLinks(x.id)}<button class="primary">Speichern</button></form>`);$('#form').onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));delete data.files;if(data.end&&data.start&&data.end<data.start)return toast('Ende muss nach dem Start liegen.');let d=data.depends,seen=new Set([x.id]);while(d){if(seen.has(d))return toast('Abhängigkeit würde einen Kreis erzeugen.');seen.add(d);d=state.tasks.find(t=>t.id===d)?.depends}Object.assign(x,data);if(!id)state.tasks.push(x);cascade();await attach(e.target.files.files,x.project,x.id);await save();$('#modal').close();render()}}
function shift(date,days){let d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)}function days(a,b){return Math.round((new Date(b+'T12:00Z')-new Date(a+'T12:00Z'))/86400000)}function cascade(){for(let i=0;i<state.tasks.length;i++)for(let t of state.tasks){let p=state.tasks.find(x=>x.id===t.depends);if(p?.end&&t.start&&t.start<=p.end){let duration=t.end?days(t.start,t.end):0;t.start=shift(p.end,1);t.end=shift(t.start,duration)}}}
function editEntry(id,type='Rapport'){let x=state.entries.find(t=>t.id===id)||{id:uid(),project:chosen()||'1',date:today(),type};show(`<h2>${id?'Eintrag bearbeiten':type+' erstellen'}</h2><form id="form"><label>Projekt<select name="project">${options(x.project)}</select></label><div class="fields">${select('type','Art',['Rapport','Baustellenjournal','Jour fixe'],x.type)}${input('date','Datum',x.date,'date','required')}${input('owner','Ersteller / Teilnehmer',x.owner)}${x.type==='Rapport'?input('order','Auftragsnummer',x.order,'text','placeholder="z. B. 1260025.002"'):''}${x.type==='Rapport'?`<label>Mitarbeiter<select name="employee"><option value="">Manuell / noch auswählen</option>${state.employees.map(a=>`<option value="${esc(a.name)}" ${x.employee===a.name?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label>`:''}${input('hours','Arbeitsstunden gesamt',x.hours||0,'number','min="0" step="0.25"')}${x.type==='Rapport'?input('normalHours','Normalstunden',x.normalHours??x.hours??0,'number','min="0" step="0.25"')+input('overtimeHours','Überstunden',x.overtimeHours||0,'number','min="0" step="0.25"')+input('normalRate','Ansatz Normalstunden CHF/h',x.normalRate||0,'number','min="0" step="0.05"')+input('overtimeRate','Ansatz Überstunden CHF/h',x.overtimeRate||0,'number','min="0" step="0.05"'):''}</div>${input('title','Titel',x.title,'text','required')}<label>Leistungen / Beobachtungen / Beschlüsse / Pendenzen<textarea name="text" required>${esc(x.text)}</textarea></label>${x.type==='Rapport'?`<label><input type="checkbox" name="verified" value="true" ${x.verified?'checked':''}> Werte mit Originalrapport abgeglichen und geprüft</label>`:''}<label>Fotos, PDFs und weitere Nachweise<input name="files" type="file" multiple accept="image/*,.pdf,.docx,.xlsx"></label>${fileLinks(x.id)}<button class="primary">Speichern</button></form>`);$('#form').onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));delete data.files;data.verified=data.verified==='true';let changes=id?Object.keys(data).filter(k=>String(x[k]??'')!==String(data[k])).map(k=>`${k}: ${x[k]||'leer'} → ${data[k]}`).join('; '):'Erstellt';if(x.type==='Rapport'){let emp=state.employees.find(a=>a.name===data.employee);if(emp){if(!data.normalRate||Number(data.normalRate)===0)data.normalRate=emp.normalRate;if(!data.overtimeRate||Number(data.overtimeRate)===0)data.overtimeRate=emp.overtimeRate}data.hours=Number(data.normalHours||0)+Number(data.overtimeHours||0)}Object.assign(x,data,{history:(x.history||'')+'\n'+new Date().toLocaleString('de-CH')+': '+changes});if(!id)state.entries.push(x);await attach(e.target.files.files,x.project,x.id);await save();$('#modal').close();render()}}
function reportAmount(e){return Number(e.normalHours??e.hours??0)*Number(e.normalRate||0)+Number(e.overtimeHours||0)*Number(e.overtimeRate||0)}
function editEmployees(){show(`<h2>Mitarbeitende und Stundenansätze</h2><form id="empform">${input('name','Name')}${input('normalRate','Normalansatz CHF/h','0','number','min="0" step="0.05"')}${input('overtimeRate','Überstundenansatz CHF/h','0','number','min="0" step="0.05"')}<button class="primary">Mitarbeiter hinzufügen</button></form><div class="tablewrap" style="margin-top:20px"><table><tr><th>Name</th><th>Normal CHF/h</th><th>Überstunden CHF/h</th><th></th></tr>${state.employees.map((e,i)=>`<tr><td>${esc(e.name)}</td><td>${money(e.normalRate)}</td><td>${money(e.overtimeRate)}</td><td><button type="button" onclick="removeEmployee(${i})">Entfernen</button></td></tr>`).join('')}</table></div>`);$('#empform').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));state.employees.push({name:d.name.trim(),normalRate:Number(d.normalRate),overtimeRate:Number(d.overtimeRate)});await save();editEmployees();render()}}
async function removeEmployee(i){state.employees.splice(i,1);await save();editEmployees()}
function exportRapportCSV(){let rs=state.entries.filter(match).filter(e=>e.type==='Rapport'),rows=[['Auftrag','Projekt','Datum','Mitarbeiter','Titel','Normalstunden','Überstunden','Ansatz normal CHF/h','Ansatz Überstunden CHF/h','Stunden total','Betrag CHF','Geprüft'],...rs.map(e=>[e.order||'',projectName(e.project),e.date||'',e.employee||e.owner||'',e.title||'',Number(e.normalHours??e.hours??0),Number(e.overtimeHours||0),Number(e.normalRate||0),Number(e.overtimeRate||0),Number(e.hours||0),reportAmount(e),e.verified?'Ja':'Nein'])];let csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(';')).join('\r\n');download(csv,'Navolta-Rapportuebersicht-'+today()+'.csv','text/csv;charset=utf-8')}
async function copyEntry(id){let old=state.entries.find(e=>e.id===id),x={...old,id:uid(),date:today(),title:old.title+' – Kopie',history:'Kopiert aus '+old.title+' vom '+fmt(old.date)};state.entries.push(x);await save();editEntry(x.id)}
const readData=f=>new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)});async function attach(files,project,parent){for(let f of files){if(f.size>25*1024*1024){toast(f.name+': maximal 25 MB pro Datei');continue}state.files.push({id:uid(),project,parent,name:f.name,size:f.size,type:f.type,data:await readData(f)})}}
function editMaterialOrder(id){let x=(state.materialOrders||[]).find(o=>o.id===id)||{id:uid(),project:chosen()||'1',status:'Bestellt',date:today()};show(`<h2>${id?'Materialbestellung bearbeiten':'Materialbestellung erfassen'}</h2><form id="matform"><label>Projekt<select name="project">${options(x.project)}</select></label><div class="fields">${input('number','Bestellnummer',x.number,'text','placeholder="Bestellnummer / Referenz"')}${input('supplier','Lieferant',x.supplier)}${input('title','Material / Beschreibung',x.title,'text','required')}${input('amount','Bestellwert inkl. MWST CHF',x.amount,'number','min="0" step="0.01"')}${input('date','Bestelldatum',x.date,'date')}${input('delivery','Voraussichtlicher Liefertermin',x.delivery,'date')}${select('status','Status',['Bestellt','Teilweise geliefert','Geliefert','Abgeschlossen','Verspätet','Storniert'],x.status||'Bestellt')}${input('contact','Kontakt / Referenz',x.contact)}</div><label>Notizen<textarea name="note">${esc(x.note)}</textarea></label><label>Lieferschein(e), Rechnung oder Bestellbestätigung anhängen<input name="files" type="file" multiple accept=".pdf,image/*,.docx,.xlsx"></label>${fileLinks(x.id)}<button class="primary">Bestellung speichern und Belege ablegen</button></form>`);$('#matform').onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));delete data.files;Object.assign(x,data);if(!state.materialOrders)state.materialOrders=[];if(!id)state.materialOrders.push(x);await attach(e.target.files.files,x.project,x.id);await save();$('#modal').close();render();toast('Materialbestellung und zugeordnete Belege gespeichert.')}}
function uploadDialog(){show(`<h2>Dokumente ablegen</h2><form id="form"><label>Projekt<select name="project">${options(chosen()||'1')}</select></label><label>Zuordnung<select name="parent"><option value="">Projektablage</option>${[...state.tasks,...state.entries,...state.invoices,...(state.materialOrders||[])].map(x=>`<option value="${x.id}">${esc(projectName(x.project))}: ${esc(x.title||x.number)}</option>`).join('')}</select></label><label>Dateien<input name="files" type="file" multiple required></label><button class="primary">Ablegen</button></form>`);$('#form').onsubmit=async e=>{e.preventDefault();let f=e.target;let parent=[...state.tasks,...state.entries,...state.invoices,...(state.materialOrders||[])].find(x=>x.id===f.parent.value);await attach(f.files.files,parent?.project||f.project.value,f.parent.value);await save();$('#modal').close();render()}}
async function removeFile(id){if(!confirm('Datei endgültig aus dem Cockpit entfernen?'))return;state.files=state.files.filter(f=>f.id!==id);await save();render()}
function gantt(v){let ts=tasks(),scheduled=ts.filter(t=>t.start&&t.end);v.innerHTML=`<div class="actions"><button onclick="gstart=shift(gstart,-14);render()">← 2 Wochen</button><button onclick="gstart=shift(today(),-3);render()">Heute</button><button onclick="gstart=shift(gstart,14);render()">2 Wochen →</button><button class="primary" onclick="editResource()">+ Ressourcen buchen</button></div><p class="muted">${fmt(gstart)} – ${fmt(shift(gstart,89))} · Balken tageweise verschieben · Rot = heute</p><div class="gantt"><div class="ganttline"><div class="ganttlabel">Tätigkeit</div><div class="track">${Array.from({length:90},(_,i)=>`<span class="day">${shift(gstart,i).slice(8)}<br>${shift(gstart,i).slice(5,7)}</span>`).join('')}</div></div>${scheduled.map(t=>{let left=days(gstart,t.start)*28,width=(days(t.start,t.end)+1)*28;return `<div class="ganttline"><div class="ganttlabel">${esc(t.title)}${t.depends?'<small> ↳ abhängig</small>':''}</div><div class="track"><div class="todayline" style="left:${days(gstart,today())*28}px"></div><div draggable="true" class="bar" data-id="${t.id}" style="left:${left}px;width:${width}px;background:${t.status==='Erledigt'?'#61a18c':'#0087b6'}" title="${fmt(t.start)} – ${fmt(t.end)}">${esc(t.title)}</div></div></div>`}).join('')}</div><p class="muted">${ts.filter(t=>!t.start||!t.end).length} Aufgaben ohne vollständige Terminierung: ${ts.filter(t=>!t.start||!t.end).map(t=>esc(t.title)).join(' · ')}</p><h2>Ressourcenplanung</h2><p class="muted">Stunden je Person und Tag; mehr als 8 h/Tag werden als Überlastung markiert. Wochenenden werden nicht belegt.</p><div class="tablewrap"><table><tr><th>Person</th><th>Projekt / Zeitraum</th><th>Stunden pro Tag</th><th>Kapazität</th><th></th></tr>${state.resources.filter(match).map(r=>`<tr><td>${esc(r.person)}</td><td>${esc(projectName(r.project))}<small>${fmt(r.start)} – ${fmt(r.end)}</small></td><td>${r.hours}</td><td><span class="pill ${resourceOver(r)?'red':'green'}">${resourceOver(r)?'Überlastung > 8 h':'Im Rahmen'}</span></td><td><button onclick="editResource('${r.id}')">Bearbeiten</button></td></tr>`).join('')}</table></div>`;document.querySelectorAll('.bar').forEach(el=>{let start;el.ondragstart=e=>{start=e.clientX;e.dataTransfer.setData('text/plain',el.dataset.id)};el.ondragend=async e=>{if(!e.clientX)return;let delta=Math.round((e.clientX-start)/28),t=state.tasks.find(x=>x.id===el.dataset.id);t.start=shift(t.start,delta);t.end=shift(t.end,delta);cascade();await save();render()}});document.querySelectorAll('.track').forEach(el=>el.ondragover=e=>e.preventDefault())}
function resourceOver(r){for(let d=r.start;d<=r.end;d=shift(d,1)){let day=new Date(d+'T12:00Z').getUTCDay();if(day===0||day===6)continue;if(state.resources.filter(x=>x.person.trim().toLowerCase()===r.person.trim().toLowerCase()&&x.start<=d&&x.end>=d).reduce((a,x)=>a+Number(x.hours),0)>8)return true}return false}
function editResource(id){let x=state.resources.find(r=>r.id===id)||{id:uid(),project:chosen()||'1',hours:8};show(`<h2>Ressourcenbuchung</h2><form id="form"><label>Projekt<select name="project">${options(x.project)}</select></label>${input('person','Person / Team',x.person,'text','required')}<div class="fields">${input('start','Von',x.start,'date','required')}${input('end','Bis',x.end,'date','required')}${input('hours','Stunden pro Arbeitstag',x.hours,'number','required min="0.25" max="24" step="0.25"')}</div><button class="primary">Speichern</button></form>`);$('#form').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(d.end<d.start)return toast('Zeitraum prüfen');Object.assign(x,d);if(!id)state.resources.push(x);await save();$('#modal').close();render()}}
function editInvoice(id){let x=state.invoices.find(r=>r.id===id)||{id:uid(),project:chosen()||'1',paid:0};show(`<h2>Rechnung erfassen</h2><p class="muted">Scan zuerst ablegen; danach unter Dokumente „Text / OCR“ auslesen und Angaben hier prüfen.</p><form id="form"><label>Projekt<select name="project">${options(x.project)}</select></label><div class="fields">${input('number','Rechnungsnummer',x.number,'text','required')}${input('customer','Kunde',x.customer,'text','required')}${input('amount','Gesamtbetrag inkl. MWST (CHF)',x.amount,'number','required min="0.01" step="0.01"')}${input('paid','Bereits bezahlt (CHF)',x.paid||0,'number','min="0" step="0.01"')}${input('date','Rechnungsdatum',x.date,'date')}${input('due','Fällig am',x.due,'date','required')}</div>${input('address','Kundenadresse',x.address)}<label>Notizen / Zahlungsreferenz<textarea name="note">${esc(x.note)}</textarea></label><label>Rechnungsscan / Belege<input name="files" type="file" multiple accept=".pdf,image/*" capture="environment"></label>${fileLinks(x.id)}<button class="primary">Speichern</button></form>`);$('#form').onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));delete data.files;if(Number(data.paid)>Number(data.amount))return toast('Zahlung übersteigt Rechnungsbetrag.');Object.assign(x,data);x.status=balance(x)===0?'Bezahlt':'Offen';if(!id)state.invoices.push(x);await attach(e.target.files.files,x.project,x.id);await save();$('#modal').close();render();paymentAlert()}}
let alertKey='';function paymentAlert(force=false){let rows=state.invoices.filter(overdue),key=rows.map(x=>x.id+balance(x)+x.due).join();if(!rows.length){if(force)toast('Keine überfälligen Rechnungen.');return}if(!force&&key===alertKey)return;if($('#modal').open)return;alertKey=key;show(`<h2>Zahlung noch nicht erfasst</h2><p>${rows.length} Rechnungen sind überfällig. Bitte Zahlungseingang prüfen und den Status aktualisieren.</p>${rows.map(x=>`<p><b>${esc(x.number)} · ${esc(x.customer)}</b><br>Fällig ${fmt(x.due)} · Rest ${money(balance(x))}</p>`).join('')}<button class="primary" onclick="$('#modal').close();nav('Debitoren')">Debitoren öffnen</button>`)}
async function processFile(id){let f=state.files.find(x=>x.id===id);show(`<h2>Dokument verarbeiten</h2><p id="ocrstatus">${esc(f.name)} · Text wird ausgelesen …</p><textarea id="ocrtext" style="height:320px">${esc(f.text||'')}</textarea><div class="actions"><button onclick="saveText('${id}')">Text speichern</button><button onclick="useText()">Für KI-Anfrage verwenden</button></div><p class="muted">Erkennung kontrollieren. Angaben werden nicht ungeprüft in Rechnungen übernommen.</p>`);if(f.text){$('#ocrstatus').textContent='Gespeicherter Text';return}try{let blob=await (await fetch(f.data)).blob(),text='',worker;async function ocr(img){worker??=await Tesseract.createWorker('eng',1,{workerPath:'vendor/worker.min.js',corePath:'vendor/',langPath:'https://tessdata.projectnaptha.com/4.0.0/',gzip:false,logger:m=>{if($('#ocrstatus'))$('#ocrstatus').textContent=(m.status||'OCR')+' '+Math.round((m.progress||0)*100)+' %'}});return (await worker.recognize(img)).data.text}if(f.type==='application/pdf'||f.name.toLowerCase().endsWith('.pdf')){let pdfjs=await import('./vendor/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc='./vendor/pdf.worker.mjs';let pdf=await pdfjs.getDocument({data:new Uint8Array(await blob.arrayBuffer())}).promise;for(let n=1;n<=pdf.numPages;n++){let p=await pdf.getPage(n),content=await p.getTextContent(),str=content.items.map(x=>x.str).join(' ');if(str.trim().length<20){let vp=p.getViewport({scale:1.5}),c=document.createElement('canvas');c.width=vp.width;c.height=vp.height;await p.render({canvasContext:c.getContext('2d'),viewport:vp}).promise;str=await ocr(c)}text+='Seite '+n+'\n'+str+'\n\n';if($('#ocrtext'))$('#ocrtext').value=text}}else if(f.type.startsWith('image/'))text=await ocr(blob);else text='Für diese Datei ist keine Texterkennung verfügbar. Bitte PDF oder Bild verwenden.';if(worker)await worker.terminate();f.text=text;await save();if($('#ocrtext')){$('#ocrtext').value=text;$('#ocrstatus').textContent='Auslesen abgeschlossen – bitte prüfen.'}}catch(e){if($('#ocrstatus'))$('#ocrstatus').textContent='Auslesen fehlgeschlagen: '+e.message}}
async function saveText(id){state.files.find(f=>f.id===id).text=$('#ocrtext').value;await save();toast('Text gespeichert')}function useText(){let text=$('#ocrtext').value;$('#modal').close();nav('KI-Hilfe');$('#aiExtra').value=text}
function download(data,name,type='application/octet-stream'){let b=data instanceof Blob?data:new Blob([data],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000)}
function calendar(id){let t=state.tasks.find(x=>x.id===id);if(!t.start)return toast('Bitte zuerst einen Termin eintragen.');let clean=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;'),dt=t.start.replaceAll('-',''), timed=t.id==='t17';let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Navolta//Projektcockpit//DE','BEGIN:VEVENT','UID:'+t.id+'@navolta-cockpit','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),timed?'DTSTART;TZID=Europe/Zurich:'+dt+'T133000':'DTSTART;VALUE=DATE:'+dt,timed?'DTEND;TZID=Europe/Zurich:'+dt+'T143000':'DTEND;VALUE=DATE:'+shift(t.end||t.start,1).replaceAll('-',''),'SUMMARY:'+clean(t.title),'DESCRIPTION:'+clean(projectName(t.project)+'\n'+(t.note||'')+(timed?'\nEndzeit 14:30 als Planungsannahme, bitte prüfen.':'')),'END:VEVENT','END:VCALENDAR'];download(lines.join('\r\n')+'\r\n','Navolta-Termin.ics','text/calendar')}
function reportRows(id){if(id){let x=state.entries.find(e=>e.id===id);return [{heading:x.type+' · '+x.title,text:`Projekt: ${projectName(x.project)}\nDatum: ${fmt(x.date)}\nErsteller / Teilnehmer: ${x.owner||'Offen'}\nStunden: ${x.hours||0}\n\n${x.text||''}\n\nÄnderungsverlauf:\n${x.history||''}`}]}let rows=[{heading:'Projektübersicht',text:`Erstellt am ${fmt(today())}\n${chosen()?projectName(chosen()):'Alle Projekte'}\nAusgangsinformationen vom 10.11.2026; Status gemäss manuell gepflegten Einträgen.`}];for(let p of state.projects.filter(p=>!chosen()||p.id===chosen())){rows.push({heading:p.name+' · '+p.description,text:state.tasks.filter(t=>t.project===p.id).map(t=>`${t.title}\nStatus: ${t.status} | ${fmt(t.start)} – ${fmt(t.end)}\nVerantwortlich: ${t.owner||'Offen'} | ${t.hours||0} h\n${t.note||''}`).join('\n\n')});}rows.push({heading:'Ressourcen',text:state.resources.filter(match).map(x=>`${x.person} · ${projectName(x.project)} · ${fmt(x.start)} – ${fmt(x.end)} · ${x.hours} h/Tag${resourceOver(x)?' · Überlastung':''}`).join('\n')||'Noch keine Ressourcen gebucht.'});rows.push({heading:'Rapporte / Baustellenjournal / Jour fixe',text:state.entries.filter(match).map(x=>`${fmt(x.date)} · ${projectName(x.project)} · ${x.type}: ${x.title}\n${x.text}`).join('\n\n')||'Noch keine Einträge.'});rows.push({heading:'Debitoren',text:state.invoices.filter(match).map(x=>`${x.number} · ${x.customer} · ${money(x.amount)} · Rest ${money(balance(x))} · Fällig ${fmt(x.due)}${overdue(x)?' · Überfällig':''}`).join('\n')||'Noch keine Rechnungen erfasst.'});return rows}
async function exportReport(type,id){try{toast('Export wird erstellt …');let rows=reportRows(id),images=id?state.files.filter(f=>f.parent===id&&f.type.startsWith('image/')):[];if(type==='pdf')await makePDF(rows,images,'Navolta-'+(id?'Rapport':'Management')+'.pdf');else await makeWord(rows,images);toast('Export erstellt')}catch(e){toast('Export fehlgeschlagen: '+e.message)}}
async function makePDF(rows,images=[],filename='Navolta-Bericht.pdf'){const {PDFDocument,StandardFonts,rgb}=PDFLib,pdf=await PDFDocument.create(),font=await pdf.embedFont(StandardFonts.Helvetica),bold=await pdf.embedFont(StandardFonts.HelveticaBold),logo=await pdf.embedPng(await (await fetch('../navolta-logo.png')).arrayBuffer());let page,y,count=0;const clean=s=>String(s).replace(/[–—]/g,'-').replace(/→/g,'>').replace(/[^\x20-\x7e\xa0-\xff\n]/g,'');function add(){page=pdf.addPage([595.28,841.89]);count++;page.drawImage(logo,{x:395,y:784,width:170,height:38});page.drawText('NAVOLTA AG | PROJEKTCOCKPIT',{x:30,y:795,size:9,font,color:rgb(.25,.4,.5)});page.drawLine({start:{x:30,y:773},end:{x:565,y:773},color:rgb(.8,.86,.9)});page.drawText(fmt(today())+' | Seite '+count,{x:30,y:24,size:9,font});y=744}function line(s,size=12,isBold=false){let f=isBold?bold:font,words=clean(s).split(/\s+/),l='';for(let w of words){if(f.widthOfTextAtSize(l+w,size)>530&&l){draw(l);l=''}while(f.widthOfTextAtSize(w,size)>530){let n=w.length;while(f.widthOfTextAtSize(w.slice(0,n),size)>530)n--;draw(w.slice(0,n));w=w.slice(n)}l+=w+' '}draw(l);function draw(t){if(y<55)add();page.drawText(t,{x:30,y,size,font:f,color:rgb(.1,.2,.27)});y-=size*1.4}}add();line('Projektbericht',16,true);y-=10;for(let r of rows){if(y<110)add();line(r.heading,14,true);y-=5;for(let s of r.text.split('\n'))line(s);y-=14}for(let f of images){try{let data=await imagePng(f.data),im=await pdf.embedPng(data),scale=Math.min(530/im.width,320/im.height),h=im.height*scale;if(y-h<55)add();page.drawImage(im,{x:30,y:y-h,width:im.width*scale,height:h});y-=h+18;line(f.name,10)}catch{line('Foto nicht exportierbar: '+f.name)}}let bytes=await pdf.save();if(filename)download(bytes,filename,'application/pdf');return bytes}
async function imagePng(data){let img=new Image();img.src=data;await img.decode();let c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;c.getContext('2d').drawImage(img,0,0);return new Uint8Array(await (await fetch(c.toDataURL('image/png'))).arrayBuffer())}
async function makeWord(rows,images){const {Document,Packer,Paragraph,TextRun,Header,Footer,ImageRun,AlignmentType,PageNumber}=docx;let logo=new Uint8Array(await (await fetch('../navolta-logo.png')).arrayBuffer());let children=[new Paragraph({children:[new TextRun({text:'Projektbericht',bold:true,size:32})],spacing:{after:240}})];for(let r of rows){children.push(new Paragraph({children:[new TextRun({text:r.heading,bold:true,size:28})],spacing:{before:240,after:120}}));for(let s of r.text.split('\n'))children.push(new Paragraph({children:[new TextRun({text:s,size:24})]}))}for(let f of images){let bytes=await imagePng(f.data);children.push(new Paragraph({children:[new ImageRun({data:bytes,type:'png',transformation:{width:450,height:280}})]}),new Paragraph(f.name))}let d=new Document({styles:{default:{document:{run:{font:'Arial',size:24}}}},sections:[{properties:{page:{margin:{top:900,right:567,bottom:567,left:567}}},headers:{default:new Header({children:[new Paragraph({alignment:AlignmentType.RIGHT,children:[new ImageRun({data:logo,type:'png',transformation:{width:200,height:45}})]})]})},footers:{default:new Footer({children:[new Paragraph({children:[new TextRun('Navolta AG · '+fmt(today())+' · Seite '),new TextRun({children:[PageNumber.CURRENT]})]})]})},children}]});download(await Packer.toBlob(d),'Navolta-Bericht.docx')}
async function exportXlsx(){let rows=[['Projekt','Tätigkeit','Status','Start','Ende','Verantwortlich','Stunden','Hinweis'],...tasks().map(t=>[projectName(t.project),t.title,t.status,t.start,t.end,t.owner,Number(t.hours||0),t.note])],invoices=[['Projekt','Rechnung','Kunde','Betrag CHF','Bezahlt CHF','Rest CHF','Fällig'],...state.invoices.filter(match).map(x=>[projectName(x.project),x.number,x.customer,Number(x.amount),Number(x.paid),balance(x),x.due])],resources=[['Projekt','Person','Start','Ende','Stunden / Tag'],...state.resources.filter(match).map(x=>[projectName(x.project),x.person,x.start,x.end,Number(x.hours)])];let z=new JSZip(),sheets=[rows,invoices,resources],xml=s=>esc(s),col=i=>String.fromCharCode(65+i);z.file('[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'+sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')+'</Types>');z.file('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');z.file('xl/workbook.xml','<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>'+['Tätigkeiten','Debitoren','Ressourcen'].map((n,i)=>`<sheet name="${n}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')+'</sheets></workbook>');z.file('xl/_rels/workbook.xml.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')+'</Relationships>');sheets.forEach((rs,i)=>z.file(`xl/worksheets/sheet${i+1}.xml`,'<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><cols><col min="1" max="8" width="28" customWidth="1"/></cols><sheetData>'+rs.map((r,j)=>`<row r="${j+1}">`+r.map((v,k)=>typeof v==='number'?`<c r="${col(k)}${j+1}"><v>${v}</v></c>`:`<c r="${col(k)}${j+1}" t="inlineStr"><is><t xml:space="preserve">${xml(v)}</t></is></c>`).join('')+'</row>').join('')+'</sheetData></worksheet>'));download(await z.generateAsync({type:'blob'}),'Navolta-Projektuebersicht.xlsx')}
function reminder(id){let x=state.invoices.find(x=>x.id===id);if(balance(x)<=0)return toast('Rechnung ist bezahlt.');show(`<h2>Zahlungserinnerung prüfen</h2><form id="remform">${input('deadline','Neue Zahlungsfrist',shift(today(),10),'date','required')}<label>Text<textarea name="body" style="height:230px">${esc(`Guten Tag\n\nFür unsere Rechnung ${x.number} vom ${fmt(x.date)} ist noch ein Betrag von ${money(balance(x))} offen. Die ursprüngliche Zahlungsfrist war der ${fmt(x.due)}.\n\nBitte überweisen Sie den offenen Betrag unter Angabe der Rechnungsnummer. Falls sich Ihre Zahlung mit diesem Schreiben überschnitten hat, betrachten Sie diese Erinnerung bitte als gegenstandslos.\n\nFreundliche Grüsse\nNavolta AG`)}</textarea></label><button class="primary">PDF erstellen und ablegen</button></form>`);$('#remform').onsubmit=async e=>{e.preventDefault();let text=e.target.body.value+'\n\nNeue Zahlungsfrist: '+fmt(e.target.deadline.value);let pdfBytes=await makePDF([{heading:'Zahlungserinnerung · '+x.number,text:x.customer+'\n'+(x.address||'')+'\n\n'+text}],[],'Navolta-Mahnung-'+x.number.replace(/[^\w-]/g,'_')+'.pdf');await attach([new File([pdfBytes],'Mahnung-'+x.number+'.pdf',{type:'application/pdf'})],x.project,x.id);x.note=(x.note||'')+'\nZahlungserinnerung erstellt '+fmt(today())+'; Frist '+e.target.deadline.value;state.entries.push({id:uid(),project:x.project,type:'Rapport',date:today(),title:'Zahlungserinnerung '+x.number,text,history:'Erstellt, Versand nicht bestätigt.'});await save();$('#modal').close();render()}}
function mailReport(){let subject='Navolta – Projekt- und Tätigkeitsübersicht '+fmt(today()),body='Hallo zusammen\n\nAnbei findet ihr die aktuelle Übersicht unserer laufenden Projekte und Tätigkeiten.\n\nBeste Grüsse\nPhilippe';show(`<h2>E-Mail an das Management vorbereiten</h2><p>Der EML-Entwurf enthält den aktuellen PDF-Bericht als Anhang. Öffne die Datei in Outlook, enthält immer info@navolta.ch und se@navolta.ch als Empfänger. Zusätzliche Empfänger kannst du ergänzen; die beiden Management-Adressen bleiben gesetzt.</p><form id="mailform">${input('to','Empfänger','info@navolta.ch; se@navolta.ch')} ${input('subject','Betreff',subject)}<label>Nachricht<textarea name="body">${esc(body)}</textarea></label><button class="primary">Entwurf mit PDF-Anhang herunterladen</button></form>`);$('#mailform').onsubmit=async e=>{e.preventDefault();let f=e.target,sub=f.subject.value,text=f.body.value,to=[...new Set(['info@navolta.ch','se@navolta.ch',...f.to.value.split(/[;,\s]+/).filter(Boolean)].map(x=>x.trim()).filter(Boolean))].join(', '),bytes=await makePDF(reportRows(),[]);let id=uid(),boundary='Navolta_'+id.replaceAll('-',''),b64=await blobBase64(new Blob([bytes]));let eml=[`To: ${to}`,`Subject: ${encodeHeader(sub)}`,'MIME-Version: 1.0',`Content-Type: multipart/mixed; boundary="${boundary}"`,'',`--${boundary}`,'Content-Type: text/plain; charset=UTF-8','Content-Transfer-Encoding: 8bit','',text,'',`--${boundary}`,'Content-Type: application/pdf; name="Navolta-Projektuebersicht.pdf"','Content-Transfer-Encoding: base64','Content-Disposition: attachment; filename="Navolta-Projektuebersicht.pdf"','',b64,`--${boundary}--`,''].join('\r\n');download(new Blob([eml],{type:'message/rfc822'}),'Navolta-Managementbericht.eml','message/rfc822');$('#modal').close();toast('E-Mail-Entwurf mit PDF-Anhang erstellt. Bitte in Outlook prüfen.')}}
function blobBase64(blob){return new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(blob)})}
function encodeHeader(s){return '=?UTF-8?B?'+btoa(unescape(encodeURIComponent(s)))+'?='}
function aiPrompt(){$('#aiOut').value='Bitte '+$('#aiKind').value+'. Keine unbekannten Angaben erfinden; offene Zuständigkeiten, Fristen und Risiken klar benennen. Sprache: Schweizer Hochdeutsch.\n\n'+JSON.stringify({projects:state.projects.filter(p=>!chosen()||p.id===chosen()),tasks:tasks(),entries:state.entries.filter(match)},null,2)+'\n\nZusatzinformationen:\n'+$('#aiExtra').value}
function backup(){download(JSON.stringify({schema:1,exported:new Date().toISOString(),state}),'Navolta-Cockpit-'+today()+'.json','application/json')}
async function restore(file){if(!file)return;try{let data=JSON.parse(await file.text());if(data.schema!==1||!['projects','tasks','entries','files','invoices','resources'].every(k=>Array.isArray(data.state?.[k])))throw Error('Ungültiges Sicherungsformat');if(!confirm('Alle bestehenden Daten durch diese Sicherung ersetzen? Vorher aktuelle Sicherung speichern.'))return;state=data.state;await save();projectSelect();render();toast('Sicherung wiederhergestellt')}catch(e){toast(e.message)}}
(async()=>{try{await openDB();let r=db.transaction('data').objectStore('data').get('state');r.onsuccess=()=>{if(r.result)state=r.result;if(!state.employees)state.employees=[];if(!state.materialOrders)state.materialOrders=[];projectSelect();render();paymentAlert();setInterval(()=>paymentAlert(),60000)}}catch(e){$('#view').innerHTML='<div class="note">Lokale Datenspeicherung nicht verfügbar. Bitte Browser-Datenspeicherung aktivieren.</div>'}})();
